SELECT assays.chembl_id AS assay_chembl_id, target_dictionary.target_type, target_dictionary.tax_id, compound_structures.canonical_smiles, molecule_dictionary.chembl_id AS molecule_chembl_id, activities.standard_type, activities.pchembl_value FROM activities INNER JOIN assays ON activities.assay_id = assays.assay_id INNER JOIN target_dictionary ON target_dictionary.tid = assays.tid INNER JOIN molecule_dictionary ON molecule_dictionary.molregno = activities.molregno INNER JOIN compound_structures ON compound_structures.molregno = molecule_dictionary.molregno WHERE target_dictionary.chembl_id = 'CHEMBL1163101' AND target_dictionary.target_type = 'SINGLE PROTEIN' AND activities.standard_type = 'IC50' AND activities.standard_relation = '=' AND activities.pchembl_value IS NOT NULL ORDER BY molecule_chembl_id, assay_chembl_id, canonical_smiles, target_type, tax_id, standard_type, pchembl_value LIMIT 1000
